                                  '    func '
                                  'testVenueOpenCancelPreservesNilEmptyAndHistoricalBytesWithoutWrites() '
                                  'throws {\n'
                                  '        for raw in [nil, "", "  custom venue  ", "Cafe\\u{301}", "博物馆 "] '
                                  'as [String?] {\n'
                                  '            var seed = TemplateAuthoringDraft(title: "Venue"); '
                                  'seed.usageLocation = raw\n'
                                  '            let (model, owner, store) = try setup(seed)\n'
                                  '            let editor = TemplateAuthoringVenueEditor(model: model), '
                                  'generation = model.metadataGeneration\n'
                                  '            XCTAssertTrue(editor.canEdit)\n'
                                  '            XCTAssertEqual(editor.savedRawValue.map { Data($0.utf8) }, '
                                  'raw.map { Data($0.utf8) })\n'
                                  '            XCTAssertNil(editor.selected)\n'
                                  '            XCTAssertEqual(editor.hasHistoricalValue, raw?.isEmpty == '
                                  'false)\n'
                                  '            editor.close()\n'
                                  '            XCTAssertFalse(editor.select(.museum)); '
                                  'XCTAssertNil(editor.savedRawValue)\n'
                                  '            XCTAssertEqual(model.metadataGeneration, generation)\n'
                                  '            XCTAssertEqual(model.draft, seed); '
                                  'XCTAssertEqual(model.coordinator.draft, seed)\n'
                                  '            XCTAssertEqual(model.draft.usageLocation.map { Data($0.utf8) '
                                  '}, raw.map { Data($0.utf8) })\n'
                                  '            XCTAssertNil(try store.active(session: '
                                  'XCTUnwrap(owner.value)))\n'
                                  '            XCTAssertFalse(model.coordinator.canSubmit)\n'
                                  '        }\n'
                                  '    }\n'
                                  '    func '
                                  'testEveryVenueSelectionChangesOnlyItsFieldAndSurvivesLocalSaveRestore() '
                                  'throws {\n'
                                  '        for preset in TemplateVenuePreset.allCases {\n'
                                  '            var seed = '
                                  'TemplateAuthoringSyntheticFixtures.compoundDraft()\n'
                                  '            seed.usageLocation = " Historical venue "; seed.players = " '
                                  '3-5 "; seed.categoryId = 73\n'
                                  '            let (model, owner, store) = try setup(seed)\n'
                                  '            let editor = TemplateAuthoringVenueEditor(model: model)\n'
                                  '            XCTAssertTrue(editor.select(preset)); '
                                  'XCTAssertFalse(editor.canRead)\n'
                                  '            var expected = seed; expected.usageLocation = '
                                  'preset.storedValue\n'
                                  '            XCTAssertEqual(model.draft, expected); '
                                  'XCTAssertEqual(model.coordinator.draft, expected)\n'
                                  '            XCTAssertFalse(editor.select(.park)); '
                                  'XCTAssertEqual(model.draft, expected)\n'
                                  '            model.save(); model.leave()\n'
                                  '            let reopened = TemplateAuthoringCoordinator(store: store, '
                                  'currentSession: { owner.value })\n'
                                  '            reopened.open(); reopened.restoreDraft()\n'
                                  '            XCTAssertEqual(reopened.draft, expected); '
                                  'XCTAssertFalse(reopened.canSubmit)\n'
                                  '            XCTAssertNil(try store.pending(session: '
                                  'XCTUnwrap(owner.value), identity: reopened.identity))\n'
                                  '        }\n'
                                  '    }\n'
                                  '    func '
                                  'testCurrentVenueSelectionIsNoopAndFreshPresentationCanSelectAgain() '
                                  'throws {\n'
                                  '        var seed = TemplateAuthoringDraft(title: "Venue"); '
                                  'seed.usageLocation = "博物馆"\n'
                                  '        let (model, _, _) = try setup(seed), generation = '
                                  'model.metadataGeneration\n'
                                  '        let editor = TemplateAuthoringVenueEditor(model: model)\n'
                                  '        XCTAssertEqual(editor.selected, .museum); '
                                  'XCTAssertFalse(editor.hasHistoricalValue)\n'
                                  '        XCTAssertTrue(editor.select(.museum)); '
                                  'XCTAssertEqual(model.metadataGeneration, generation)\n'
                                  '        XCTAssertEqual(model.draft, seed); '
                                  'XCTAssertEqual(model.coordinator.draft, seed)\n'
                                  '        XCTAssertFalse(editor.select(.park))\n'
                                  '        let fresh = TemplateAuthoringVenueEditor(model: model)\n'
                                  '        XCTAssertTrue(fresh.select(.park)); '
                                  'XCTAssertEqual(model.coordinator.draft.usageLocation, "公园绿地")\n'
                                  '    }\n'
                                  '    func testVenueCallbacksRetireAcrossDraftAndSessionChanges() throws {\n'
