                                  '    }\n'
                                  '    func '
                                  'testVenueStaleCanonicalEquivalentBytesAreRejectedBeforeParentChangeCallback() '
                                  'throws {\n'
                                  '        var seed = TemplateAuthoringDraft(title: "Venue"); '
                                  'seed.usageLocation = "Cafe\\u{301}"\n'
                                  '        let (model, _, _) = try setup(seed), editor = '
                                  'TemplateAuthoringVenueEditor(model: model)\n'
                                  '        model.draft.usageLocation = "Caf\\u{e9}"\n'
                                  '        XCTAssertEqual(model.draft, seed) // Swift String equality is '
                                  'canonical, the venue lease must be byte-exact.\n'
                                  '        XCTAssertFalse(editor.canRead); '
                                  'XCTAssertFalse(editor.select(.museum))\n'
                                  '        XCTAssertEqual(model.draft.usageLocation.map { Data($0.utf8) }, '
