                                  '        let reopened = TemplateAuthoringCoordinator(store: store, '
                                  'currentSession: { owner.value })\n'
                                  '        let restored = TemplateAuthoringModel(coordinator: reopened); '
                                  'restored.load()\n'
                                  '        let old = TemplateAuthoringVenueEditor(model: restored)\n'
                                  '        XCTAssertFalse(old.canEdit); restored.restore(); '
                                  'XCTAssertFalse(old.select(.museum))\n'
                                  '        XCTAssertEqual(restored.draft.usageLocation, seed.usageLocation)\n'
                                  '        let beforeReview = TemplateAuthoringVenueEditor(model: restored)\n'
                                  '        restored.prepare(.saveDraft); XCTAssertNotNil(restored.review)\n'
                                  '        XCTAssertFalse(beforeReview.select(.museum))\n'
                                  '        let duringReview = TemplateAuthoringVenueEditor(model: restored)\n'
                                  '        XCTAssertFalse(duringReview.select(.museum)); '
                                  'XCTAssertEqual(restored.draft.usageLocation, seed.usageLocation)\n'
