                                  "attr='dumps', ctx=Load()), args=[Name(id='_value', ctx=Load())], "
                                  "keywords=[keyword(arg='sort_keys', value=Constant(value=True)), "
                                  "keyword(arg='separators', value=Tuple(elts=[Constant(value=','), "
                                  "Constant(value=':')], ctx=Load())), keyword(arg='ensure_ascii', "
                                  'value=Constant(value=True))]))], decorator_list=[], type_params=[])", '
                                  '\'json_pretty_bytes\': "FunctionDef(name=\'_pure\', '
                                  "args=arguments(posonlyargs=[], args=[arg(arg='_value')], kwonlyargs=[], "
                                  'kw_defaults=[], defaults=[]), '
                                  "body=[Return(value=Call(func=Attribute(value=BinOp(left=Call(func=Attribute(value=Name(id='json', "
                                  "ctx=Load()), attr='dumps', ctx=Load()), args=[Name(id='_value', "
                                  "ctx=Load())], keywords=[keyword(arg='ensure_ascii', "
                                  "value=Constant(value=False)), keyword(arg='indent', "
                                  "value=Constant(value=2))]), op=Add(), right=Constant(value='\\\\n')), "
                                  "attr='encode', ctx=Load()), args=[], keywords=[]))], decorator_list=[], "
                                  'type_params=[])"}\n'
                                  '\n'
                                  'def _club_copy_json(value, stack=None):\n'
                                  '    kind=type(value)\n'
                                  '    if kind in (str,int,float,bool,type(None)):return value\n'
                                  "    if kind not in (list,tuple,dict):raise TypeError('Pure calculation "
                                  "accepts exact JSON builtins only')\n"
                                  '    stack=set() if stack is None else stack\n'
                                  "    if id(value) in stack:raise ValueError('Circular JSON input')\n"
                                  '    stack.add(id(value))\n'
                                  '    try:\n'
                                  '        if kind is dict:\n'
