                                  "declaration')\n"
                                  '    '
                                  "node=nodes[0];lines=raw.decode().splitlines(True);source=''.join(lines[node.lineno-1:node.end_lineno]).encode()\n"
                                  "    if _hash(source).hexdigest()!=row['source_sha256']:raise "
                                  "ValueError('Changed complete pure declaration')\n"
                                  '    # Compare AST after only the declared parameter/function-name '
                                  'normalization.\n'
                                  '    if node.decorator_list or len(node.args.args)!=1 or '
                                  'node.args.posonlyargs or node.args.kwonlyargs or node.args.vararg or '
                                  'node.args.kwarg or node.args.defaults or node.returns or '
                                  "node.args.args[0].annotation:raise ValueError('Impure declaration "
                                  "signature')\n"
