                                  '    class Normalize(_club_ast.NodeTransformer):\n'
                                  '        def visit_Name(self,n):\n'
                                  "            if n.id==parameter:n.id='_value'\n"
                                  '            return n\n'
                                  '    '
                                  "node=Normalize().visit(node);node.name='_pure';node.args.args[0].arg='_value'\n"
                                  '    shape=_club_ast.dump(node,include_attributes=False)\n'
                                  "    if shape!=row['shape'] or "
                                  "shape!=_CLUB_PURE_SHAPES.get(row['kind']):raise ValueError('Impure "
                                  "same-name function refused')\n"
