                                  '_club_transaction_owner()}\n'
                                  '                token = call_frame.set(frame)\n'
                                  "            elif not frame['active'] or frame['owner'] != "
                                  '_club_transaction_owner():\n'
                                  "                raise ValueError('Expired or foreign historical reader "
                                  "call frame')\n"
                                  '            try:\n'
                                  '                result = function(*args, **kwargs)\n'
                                  '            finally:\n'
                                  '                if outermost:\n'
                                  "                    frame['active'] = False\n"
                                  '                    call_frame.reset(token)\n'
                                  '                    verify()\n'
                                  '            return guard_result(result)\n'
                                  '        # Keep one wrapper per callable identity, including '
                                  'already-bound\n'
                                  '        # readers; do not trust caller-mutable function marker '
                                  'attributes.\n'
                                  '        guarded_functions[id(function)] = (function, checked)\n'
                                  '        guarded_functions[id(checked)] = (checked, checked)\n'
                                  '        return checked\n'
                                  '\n'
                                  '    def load_name(local):\n'
                                  '        if local in modules:\n'
                                  '            return modules[local]\n'
                                  "        relative = local.replace('.', '/') + '.py'\n"
                                  '        is_package = local in packages\n'
                                  "        init = (local.replace('.', '/') + '/' if local else '') + "
                                  "'__init__.py'\n"
                                  '        if is_package:\n'
                                  '            relative = init if init in expected else None\n'
                                  '        elif relative not in expected:\n'
                                  "            raise ModuleNotFoundError('Module outside finite e2b "
                                  "namespace: ' + local)\n"
                                  "        qualified = namespace + ('.' + local if local else '')\n"
                                  '        module = _ClubModule(qualified)\n'
                                  '        module.__package__ = qualified if is_package else '
                                  "qualified.rpartition('.')[0]\n"
                                  '        if is_package:\n'
                                  "            module.__path__ = [str(context.root / local.replace('.', "
                                  "'/'))]\n"
                                  '        modules[local] = module\n'
