                                  'let reopened = openField(\\"introduction\\"); '
                                  'XCTAssertEqual(reopened.value as? String, original)\\n        '
                                  'reopened.tap(); reopened.typeText(\\" New bio\\"); applyField()\\n        '
                                  'XCTAssertTrue(app.buttons[\\"profile.fieldEdit.open.introduction\\"].label.contains(\\"New '
                                  'bio\\"))\\n        '
                                  'XCTAssertTrue(app.buttons[\\"profile.fieldEdit.open.name\\"].label.contains(\\"Staged\\"))\\n    '
                                  '}\\n    func testSwipeDismissDiscardsOnlyLocalFieldScratch() {\\n        '
                                  'launch(\\"success\\")\\n        let field = openField(\\"name\\"), '
                                  'original = field.value as? String\\n        field.tap(); '
                                  'field.typeText(\\" Cancelled\\")\\n        let navigation = '
                                  'app.navigationBars.element(boundBy: app.navigationBars.count - '
                                  '1)\\n        navigation.swipeDown()\\n        '
                                  'XCTAssertTrue(app.buttons[\\"profile.fieldEdit.open.name\\"].waitForExistence(timeout: '
                                  '5))\\n        let reopened = openField(\\"name\\"); '
                                  'XCTAssertEqual(reopened.value as? String, original)\\n    }\\n    func '
                                  'testBackgroundKeepsFieldScratchUntilExplicitCancel() {\\n        '
                                  'launch(\\"success\\")\\n        let field = openField(\\"name\\"), '
                                  'original = field.value as? String\\n        field.tap(); '
                                  'field.typeText(\\" Retained\\")\\n        XCUIDevice.shared.press(.home); '
                                  'app.activate()\\n        XCTAssertTrue(field.waitForExistence(timeout: '
                                  '5))\\n        XCTAssertTrue((field.value as? '
